$posts=[
 ["Xây dựng thói quen đọc trong thời đại số","xay-dung-thoi-quen-doc",2,"published","Mười lăm phút đọc mỗi ngày trước khi mở máy tính có thể mở ra những góc nhìn mới. Bắt đầu bằng một chương sách ngắn và đặt điện thoại úp xuống ở bàn bên cạnh.","Đặt điện thoại ra ngoài tầm tay trong mười lăm phút đầu tiên","Trở ngại lớn nhất khi đọc một cuốn sách chuyên ngành hay tản văn dài không phải là thiếu thời gian, mà là thói quen cầm điện thoại kiểm tra tin nhắn cứ mỗi năm phút. Nhóm thử áp dụng một quy tắc nhỏ: pha một cốc trà ấm, úp màn hình điện thoại xuống bàn bên cạnh và chỉ đặt mục tiêu đọc trọn vẹn 10 đến 15 trang giấy trước khi bật máy tính làm việc.","Tóm tắt lại bằng một câu của chính mình","Thay vì gạch dưới kín cả trang sách, sau mỗi chương ngắn hãy gấp sách lại và viết đúng một câu tóm tắt ý cốt lõi vào sổ tay bằng ngôn ngữ của mình. Chính những câu ghi chú ngắn ấy lại trở thành nguồn chất liệu tự nhiên nhất khi cần viết bài chia sẻ trên Góc Nhìn.",1,"assets/images/cover-2.svg"],
 ["Từ ý tưởng đến một website đầu tiên bằng PHP","website-dau-tien-bang-php",1,"published","Một hành trình nhỏ từ form HTML đến dữ liệu được lưu trong database, dành cho người vừa bắt đầu làm quen với mô hình MVC và PDO trong PHP thuần.","Bài học từ tuần đầu viết gộp SQL chung với giao diện","Ở những buổi đầu dựng thử trang tin tức trên XAMPP, phản xạ tự nhiên của người mới học là đặt câu lệnh SELECT và INSERT ngay trong cùng một tệp HTML cho nhanh thấy kết quả. Nhưng chỉ sau vài ngày, khi một bạn trong nhóm chỉnh lại khung thẻ bài viết thì vô tình làm mất biến kiểm tra CSRF của biểu mẫu lưu nháp. Từ sự cố đó, nhóm quyết định dừng lại một buổi tối để tách toàn bộ mã nguồn về đúng ba lớp: Router và Controller nhận yêu cầu ở cổng vào, Model xử lý giao dịch PDO có khóa dòng FOR UPDATE, còn View chỉ đảm nhiệm trình bày và thoát mã HTML bằng hàm e().","Giữ luồng dữ liệu an toàn từ những chi tiết nhỏ","Khi tự viết hệ thống không dựa vào framework lớn, từng bước kiểm tra đều giúp cả nhóm hiểu sâu cách trình duyệt và máy chủ giao tiếp: từ việc truyền mã phiên bản (version) ẩn trong biểu mẫu để hai biên tập viên không duyệt đè lên nhau, lọc thẻ HTML bằng HTML Purifier trước khi lưu vào MySQL, cho đến việc kiểm tra định dạng thực của ảnh tải lên bằng finfo thay vì chỉ tin vào đuôi tệp.",1,"assets/images/cover-1.svg"],
 ["Một buổi sáng chậm giữa nhịp sống thành phố","buoi-sang-cham",2,"published","Rời bàn máy tính sớm hơn hai mươi phút, đi bộ dưới hàng cây lúc nắng mới lên để đầu óc tỉnh táo trước khi bắt đầu một ngày học và sửa lỗi chương trình.","Hai mươi phút không màn hình trước giờ vào ca học sáng","Sau những buổi tối thức khuya rà lỗi giao diện và cơ sở dữ liệu, việc mở mắt ra là nhìn ngay vào màn hình điện thoại thường khiến cả buổi sáng rơi vào trạng thái uể oải. Thử dậy sớm hơn 20 phút, đi bộ hoặc đạp xe chậm rãi qua đoạn đường có bóng cây quanh trường giúp mắt được điều tiết ở khoảng nhìn xa tự nhiên.","Giải pháp cho những lỗi code khó thường đến lúc đi bộ","Rất nhiều lần trong lúc đang bước đi thoải mái mà không nhìn vào dòng lệnh nào, các thành viên trong nhóm lại chợt nhận ra nguyên nhân thật sự của một lỗi khóa ngoại hay lỗi tràn khung CSS tối hôm trước. Một nhịp nghỉ ngắn đầu ngày chính là khoản đầu tư hiệu quả nhất cho sự tập trung.",0,"assets/images/cover-6.svg"],
 ["Ghi chép có hệ thống để học sâu hơn","ghi-chep-co-he-thong",3,"published","Chia trang sổ tay thành ba vùng theo cách ghi chép Cornell: cột ý chính bên trái, nội dung thực hành bên phải và ba dòng tổng kết ở cuối trang để ôn tập nhanh trước kỳ thi.","Đặt câu hỏi ở lề trái thay vì chép nguyên lời giảng","Khi nghe giảng hoặc đọc tài liệu kỹ thuật dài, việc cố chép lại từng chữ khiến chúng ta không kịp suy nghĩ xem phần đó giải quyết vấn đề gì. Bằng cách kẻ một đường dọc chia trang giấy làm hai phần theo tỷ lệ 3:7, cột nhỏ bên trái chỉ dùng để ghi câu hỏi hoặc từ khóa (ví dụ: “Khi nào trả mã HTTP 409?”), còn cột bên phải ghi ví dụ minh họa ngắn gọn.","Ba dòng đúc kết ở chân trang cho lần ôn lại","Chừa lại 4 dòng trống dưới cùng mỗi trang sổ để viết phần kết luận sau buổi học 24 giờ. Khi cần ôn tập trước buổi vấn đáp đồ án, chỉ cần che cột phải và nhìn vào chuỗi câu hỏi ở cột trái để tự trả lời là biết ngay phần kiến thức nào mình đã thực sự nắm vững.",0,"assets/images/cover-3.svg"],
 ["Những góc xanh được vun trồng cùng nhau","nhung-goc-xanh",4,"published","Một nhóm sinh viên biến khoảng sân nhỏ sau giờ học thành nơi ươm những chậu hương thảo, bạc hà và chia nhau lịch trực tưới nước mỗi sáng trước khi vào lớp.","Bắt đầu từ năm chậu đất nung và bảng lịch trực viết tay","Khoảng hiên nắng gắt phía sau khu tự học từng chỉ để vài chiếc ghế gỗ cũ. Đầu học kỳ, nhóm rủ nhau mỗi người góp một việc nhỏ: người xin giống cây hương thảo và bạc hà dễ sống, người mua đất trộn trấu, người kẻ bảng lịch tưới nước dán ngay cạnh vòi nước chung. Khi công việc được chia thành từng ca 10 phút đầu giờ sáng, việc chăm cây không còn là gánh nặng của riêng ai.","Khoảng nghỉ mắt sau những giờ nhìn màn hình code","Sau hai tháng, góc bàn gỗ giữa những chậu cây xanh trở thành điểm hẹn quen thuộc để cả nhóm ngồi rà lại bài tập lớn hoặc đơn giản là đứng dậy vươn vai sau hai tiếng liền tìm lỗi SQL. Một không gian chung được tự tay chăm chút luôn tạo ra sự gắn kết tự nhiên hơn bất kỳ khẩu hiệu nào.",1,"assets/images/cover-4.svg"],
 ["Thiết kế giao diện bắt đầu từ khả năng đọc","thiet-ke-kha-nang-doc",1,"published","Cỡ chữ, khoảng cách dòng, phông chữ hỗ trợ đầy đủ dấu tiếng Việt và độ tương phản đạt chuẩn WCAG AA là nền tảng để trang báo đọc êm mắt trên cả điện thoại 320px lẫn máy tính.","Phát hiện lỗi tách dấu tiếng Việt và độ tương phản khi chạy thật","Một giao diện nhìn thoáng trên bản vẽ chưa chắc đã dễ đọc khi đổ dữ liệu tiếng Việt thực tế vào. Khi mở trang trên Chrome ở máy Windows, nhóm phát hiện các tiêu đề chứa nguyên âm ghép như “vun trồng” hay “bắt đầu” bị hở khoảng trắng ngay sau dấu mũ và dấu sắc do phông chữ Cambria và Georgia thiếu ký tự tiếng Việt dựng sẵn. Việc chuyển sang bộ phông hệ thống hỗ trợ trọn vẹn bảng mã Unicode tiếng Việt cùng độ rộng cột đọc 68 ký tự (68ch) giúp mắt người đọc theo dõi mạch bài dài mà không bị mỏi.","Đo kiểm trên cả chế độ Sáng, Tối và màn hình 320px","Thay vì đoán bằng mắt thường, nhóm dùng bộ kiểm thử tự động quét qua cả chế độ Tối (#0B0F19) và chế độ Sáng màu giấy ấm (#FAF7F2). Những chi tiết nhỏ như tăng độ đậm của nhãn trạng thái “Chờ duyệt” từ 4.1:1 lên 7.68:1, giữ kích thước vùng chạm tối thiểu 44×44px cho nút chuyển màu, hay gom gọn các mục quản trị vào menu Tòa soạn trên màn hình hẹp 320px đều xuất phát từ những lần bấm thử bằng bàn phím và điện thoại thật.",0,"assets/images/cover-5.svg"],
 ["Làm việc nhóm: bắt đầu bằng một thỏa thuận nhỏ","lam-viec-nhom",3,"published","Thống nhất cách tách cấu hình máy cá nhân, cô lập database kiểm thử và giữ hợp đồng tên trường giữa Backend với Frontend giúp nhóm 5 thành viên phối hợp nhịp nhàng.","Ba thỏa thuận nhỏ giải quyết xung đột khi ghép nhánh Git","Khi 5 thành viên cùng làm việc trên một kho mã nguồn PHP và MySQL, rắc rối đầu tiên không nằm ở thuật toán khó mà ở môi trường chạy: mỗi máy đặt mật khẩu và cổng MariaDB khác nhau, nên mỗi lần đẩy tệp cấu hình lên là máy người khác báo lỗi kết nối. Nhóm lập tức thống nhất thỏa thuận đầu tiên: tách riêng config/local.php khỏi Git, dùng scripts/build-demo.php để sinh dữ liệu mẫu chuẩn và tách hẳn cơ sở dữ liệu news_blog_cms_test cho các kịch bản kiểm thử tự động.","Kiểm tra tự động trước mỗi lần bàn giao giao diện","Để người làm giao diện yên tâm chỉnh sửa CSS và bố cục mà không làm hỏng luồng xử lý của người viết Backend, nhóm xây dựng tệp kiểm tra hợp đồng View (tests/view-contract.php) và 11 bài kiểm tra hồi quy không chạm database (tests/regression-readonly.php). Chỉ cần chạy hai lệnh kiểm tra nhanh trong vài giây, cả nhóm biết chắc các biểu mẫu đăng nhập, duyệt bài và bình luận vẫn khớp hoàn toàn.",0,"assets/images/cover-7.svg"],
 ["Nhật ký học SQL: hiểu khóa ngoại qua ví dụ","nhat-ky-hoc-sql",1,"draft","Ghi chép thực hành của nhóm khi thiết kế 8 bảng InnoDB cho Góc Nhìn: vì sao khóa ngoại chuyên mục dùng ON DELETE RESTRICT còn bảng thẻ bài viết dùng ON DELETE CASCADE.","Hiểu sự khác biệt giữa RESTRICT và CASCADE qua tình huống thật","Lý thuyết về khóa ngoại (Foreign Key) trở nên rất rõ ràng khi nhóm đặt câu hỏi: chuyện gì xảy ra nếu quản trị viên bấm xóa một chuyên mục đang có 3 bài viết đã xuất bản? Nhờ khai báo CONSTRAINT fk_posts_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT, MySQL lập tức chặn thao tác xóa đó và hệ thống hiển thị thông báo rõ ràng thay vì để lại những bài viết mồ côi không có chuyên mục.","Tự tham chiếu hai cấp cho cây bình luận","Ngược lại, ở bảng trung gian post_tags nối giữa bài viết và thẻ (Tags), nhóm chọn ON DELETE CASCADE để khi xóa một thẻ, chỉ các dòng liên kết trong bảng trung gian được dọn sạch còn bài viết gốc vẫn an toàn. Với bảng comments, cột parent_id tự tham chiếu về chính comments(id) kết hợp kiểm tra ở tầng Model giúp giữ cấu trúc thảo luận đúng 2 cấp gọn gàng.",0,"assets/images/cover-8.svg"],
 ["Kế hoạch đọc sách của câu lạc bộ","ke-hoach-doc-sach",4,"draft","Lịch sinh hoạt đọc sách tháng này của nhóm: mỗi thành viên chọn một chương ngắn về thiết kế web, cơ sở dữ liệu hoặc kỹ năng viết để trình bày trong 7 phút chiều thứ Bảy.","Mỗi người chỉ chọn một chương thực sự ứng dụng được ngay","Thay vì yêu cầu cả nhóm cùng đọc hết một cuốn sách dày 400 trang trong một tháng, câu lạc bộ nhỏ của nhóm đổi sang hình thức mỗi thành viên tự chọn một chương sách gắn trực tiếp với phần việc mình đang làm trong đồ án để tóm tắt lại cho 4 người còn lại.","Bảy phút chia sẻ và mười lăm phút hỏi đáp thực tế","Trong buổi gặp chiều thứ Bảy, mỗi người có đúng 7 phút trình bày 3 ý tâm đắc nhất và cách áp dụng thẳng vào dự án Góc Nhìn (như cách đặt độ tương phản màu hay cách viết thông báo lỗi thân thiện). Cách đọc có mục tiêu cụ thể giúp buổi sinh hoạt luôn sôi nổi và không ai bị quá tải.",0,"assets/images/cover-11.svg"],
 ["Một tuần thử học bằng sơ đồ tư duy","hoc-bang-so-do-tu-duy",3,"pending","Thử nghiệm vẽ sơ đồ tư duy cho môn Lập trình Web trong 7 ngày: từ bản nháp đầu tiên ôm đồm cả câu định nghĩa dài đến bản vẽ lại chỉ giữ từ khóa và tên bảng giúp cả nhóm nhớ chắc luồng duyệt bài.","Bản nháp ngày đầu: ôm đồm nên nhìn lại vẫn rối","Khi bắt đầu ôn tập phần phân quyền và quy trình xuất bản của đồ án Góc Nhìn, cả nhóm thử vẽ chung một sơ đồ tư duy trên giấy khổ A4. Sai lầm của ba ngày đầu là ai cũng sợ thiếu ý nên chép nguyên cả câu dài vào nhánh con, lại gom chung trạng thái bài viết (draft, pending, published, rejected) với trạng thái bình luận (pending, approved, hidden) vào cùng một cụm. Đến khi gấp tài liệu lại để tự giải thích luồng dữ liệu, không ai nhớ chính xác bước nào tăng biến version và bước nào ghi vào bảng post_history.","Phần được gạch sửa sau một tuần thực hành","Cuối tuần, nhóm quyết định gạch bỏ toàn bộ nhánh văn bản dài ở góc trái sơ đồ và vẽ lại theo 3 nguyên tắc: mỗi nhánh chỉ gắn với tên bảng hoặc tên cột thực tế trong database, tách riêng nhánh Luồng duyệt bài (4 trạng thái kèm điều kiện bắt buộc nhập lý do khi trả bài) khỏi nhánh Phân quyền 3 vai trò (USER, AUTHOR, ADMIN), và dùng mũi tên ghi rõ ràng buộc khóa ngoại (ON DELETE RESTRICT cho chuyên mục, ON DELETE CASCADE cho bảng trung gian post_tags). Bản sơ đồ sau khi sửa trở thành tài liệu tra cứu nhanh mỗi khi nhóm viết kiểm thử nghiệm thu.",0,"assets/images/cover-10.svg"],
 ["Tủ sách trao đổi ở khu sinh hoạt chung","tu-sach-trao-doi",4,"pending","Kệ gỗ hai tầng đặt ở góc phòng sinh hoạt chung với quy tắc đơn giản: ghi tên vào sổ tay khi mượn sách và kẹp lại một mảnh giấy nhỏ ghi chương tâm đắc nhất khi trả.","Để những cuốn sách giáo trình và kỹ năng không nằm yên trên giá","Nhiều cuốn sách hay về thiết kế giao diện, cấu trúc dữ liệu hay kỹ năng viết chỉ được đọc một lần rồi cất kỹ. Nhóm đặt một kệ gỗ nhỏ hai tầng ở góc phòng sinh hoạt chung kèm cuốn sổ bìa cứng kẻ sẵn ba cột: Tên sách, Người mượn và Ngày hẹn trả. Ai mang đến một cuốn sách cũ đều có thể đổi lấy một cuốn khác về đọc trong hai tuần.","Những tờ giấy ghi chú kẹp lại giữa trang sách","Điều thú vị nhất của tủ sách không chỉ nằm ở số đầu sách được luân chuyển, mà ở những mảnh giấy nhỏ người đọc trước kẹp lại ở trang họ thấy tâm đắc nhất. Người đọc sau vừa tiết kiệm thời gian tìm ý chính, vừa có cảm giác như đang trò chuyện cùng một người bạn vừa đi qua môn học đó.",0,"assets/images/cover-9.svg"],
 ["Đi tìm nhịp học phù hợp với chính mình","nhip-hoc-cua-minh",3,"rejected","Thử nghiệm chia khung giờ tự học thành các chặng 45 phút tập trung tuyệt đối kèm 10 phút nghỉ giải lao, ghi lại khung giờ bản thân viết code và đọc tài liệu hiệu quả nhất.","Quan sát khung giờ vàng của chính mình trong ba ngày liên tiếp","Không phải ai cũng học tốt lúc nửa đêm hay lúc 5 giờ sáng. Trước khi ép mình theo lịch biểu mẫu trên mạng, hãy thử ghi chú lại mức độ tập trung của bản thân qua ba khung giờ Sáng, Chiều và Tối trong 3 ngày liên tiếp để nhận ra lúc nào mình giải quyết các bài toán logic nhanh nhất.","Tách bạch giờ đọc hiểu sâu và giờ làm việc vặt","Khi đã tìm ra nhịp học riêng, hãy dành trọn khung giờ tỉnh táo nhất cho việc thiết kế cấu trúc hoặc viết mã nguồn cốt lõi, và đẩy các việc nhẹ nhàng hơn như kiểm tra chính tả, căn chỉnh ảnh bìa hay trả lời bình luận sang cuối buổi chiều.",0,"assets/images/cover-12.svg"],
];
foreach($posts as $i=>$p){
 $id=$i+1; $author=$i%2+2;
 $html='<h2>'.$p[5].'</h2><p>'.$p[6].'</p><h2>'.$p[7].'</h2><p>'.$p[8].'</p><p>Hãy chia sẻ trải nghiệm của bạn trong phần bình luận để câu chuyện có thêm những góc nhìn.</p>';
 $date=date('Y-m-d H:i:s',strtotime('2026-10-01 08:00:00')+$i*86400);
 $values=[$author,$p[2],$quote($p[0]),$quote($p[1]),$quote($p[4]),$quote($html),$quote($p[10]),$quote($p[3]),$p[9],17+$i*13,$p[3]==='published'?$quote($date):'NULL',$p[3]==='rejected'?$quote('Bổ sung ví dụ cụ thể và nguồn tham khảo cho phần hướng dẫn.'):'NULL',$quote($date)];
 $sql.="INSERT INTO posts(author_id,category_id,title,slug,excerpt,content,cover_image,status,is_featured,views,published_at,rejection_reason,created_at) VALUES (".implode(',',$values).");\n";
 $sql.="INSERT INTO post_tags(post_id,tag_id) VALUES ($id,".($i%6+1)."),($id,".(($i+2)%6+1).");\n";
 $sql.="INSERT INTO post_history(post_id,actor_id,action,to_status,note) VALUES ($id,1,'seed',".$quote($p[3]).",".$quote('Dữ liệu demo của đồ án.').");\n";
}
foreach([
 [1,4,null,'Mình bắt đầu từ mười trang mỗi tối, cảm ơn bài viết!','approved'],
 [1,2,1,'Cảm ơn bạn đã chia sẻ. Giữ nhịp đọc phù hợp với mình là điều quan trọng.','approved'],
 [1,5,null,'Mình muốn gợi ý thêm một vài cuốn sách.','pending'],
 [2,4,null,'Bình luận gốc này đã được ẩn.','hidden'],
 [2,3,4,'Phản hồi đã duyệt vẫn được giữ trong cuộc trò chuyện.','approved'],
 [2,5,null,'<script>alert("demo")</script> Nội dung này được lưu và hiển thị như văn bản.','pending'],
] as $c) $sql.="INSERT INTO comments(post_id,user_id,parent_id,content,status) VALUES (".$c[0].','.$c[1].','.($c[2]??'NULL').','.$quote($c[3]).','.$quote($c[4]).");\n";
$sql.="COMMIT;\n";
file_put_contents($root.'/database/news_blog_cms.sql',$sql);
echo "Generated database/news_blog_cms.sql\n";
